buggy.utc_to_local_max_to_gmt9_wall_year:
import numpy as np
from pandas import DatetimeIndex, Timestamp
from pandas.errors import OutOfBoundsDatetime


def wall_year(utc_val, tz):
    dti = DatetimeIndex(np.array([utc_val], dtype="i8").view("M8[ns]")).tz_localize("UTC")
    try:
        local = dti.tz_convert(tz).tz_localize(None)
        return float(local.year[0])
    except OutOfBoundsDatetime:
        return -9999.0


probe(wall_year(Timestamp.max._value, "Etc/GMT-9"))

